function area115(k=ui115.tab){return System115.area(system115(),k)}
function draft115(k=ui115.tab){const a=area115(k);return a.draft||a.published}
function actor115(){return {id:state.user,super:!!super114(),preview:!!ui114.preview||!!state.preview}}
function now115(){return ten.now||Date.now()}
function fmt115(at){if(!at)return 'Waktu tidak tercatat';const d=new Date(typeof at==='string'&&!/[Z+]\d*/.test(at)?at.replace(/$/, '+07:00'):at);return isNaN(d)?String(at):new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Jakarta'}).format(d)+' WIB'}
function route115(tab='content'){if(!super114())return toast('Menu Sistem khusus Super Admin.');if(!tabs115[tab])tab='content';closeModal();closePop();close114();close115(true);ui115.tab=tab;state.mode='platform';state.page='module';v4.module='cms';render()}
function heading115(){return `<header class="heading115"><div><span class="eyebrow115">PLATFORM / PENGELOLAAN</span><h1>Sistem</h1><p>Kelola konten, navigasi, aturan, dan telusuri perubahan.</p></div>${ui115.tab!=='activity'?B115('Riwayat versi','versions',ui115.tab,'small'):''}</header><nav class="switch104 tabs115" role="tablist" aria-label="Bagian Sistem">${Object.entries(tabs115).map(([k,n])=>`<button role="tab" aria-selected="${k===ui115.tab}" class="${k===ui115.tab?'active':''}" data-s115="tab" data-id="${k}">${T(...n)}</button>`).join('')}</nav>`}
function statusConfig115(k){const a=area115(k);return `<div class="config-status115"><div>${icon('shield')}<span><strong>Versi ${a.version} · ${a.draft?'Draf tersimpan':'Konfigurasi aktif'}</strong><small>${a.appliedAt?'Diterapkan '+fmt115(a.appliedAt):'Dasar awal prototype · perlu verifikasi sebelum produksi'}</small></span></div>${a.draft?`<div class="buttons115">${B115('Pratinjau','preview',k,'small')}${B115(k==='content'?'Tinjau publikasi':'Tinjau penerapan','review',k,'primary')}${B115('Buang draf','discard',k,'text')}</div>`:''}</div>`}
function row115(title,body,meta,action,id){return `<button class="row115" data-s115="${action}" data-id="${E(id)}"><span class="row-symbol115">${icon(action==='rule'?'clock':action==='nav-item'?'menu':'settings')}</span><span class="row-copy115"><strong>${E(title)}</strong><small>${E(body)}</small></span><span class="row-meta115">${meta}</span><i class="arrow115">↗</i></button>`}
function page115(){if(!super114())return denied9();system115();return `<div class="system-page115">${heading115()}<section class="tab-body115" role="tabpanel">${ui115.tab==='activity'?activityPage115():statusConfig115(ui115.tab)+(ui115.tab==='content'?contentPage115():ui115.tab==='navigation'?navigationPage115():ui115.tab==='maintenance'?maintenancePage115():proceduresPage115())}</section><p class="system-footnote115">Prototype lokal · perubahan konten tidak publikasikan website produksi. Pengaturan akses tetap melalui Staff & Akses.</p></div>`}
function contentPage115(){const v=draft115('content'),a=area115('content');return `<div class="section-head115"><div><h2>Susunan website</h2><p>Ubah isi setiap bagian; harga dan benefit mengikuti konfigurasi asal.</p></div>${B115('Lihat website','public-preview','content','small')}</div><section class="list115">${Object.entries(contentNames115).map(([id,name])=>{const b=v.blocks[id],diff=JSON.stringify(b)!==JSON.stringify(a.published.blocks[id]);return row115(name,b.title,statusBadge111(diff?'Draf berubah':b.visible?'Ditampilkan':'Disembunyikan',diff?'mustard':b.visible?'blue':'neutral'),'block',id)}).join('')}</section><section class="linked115"><div>${icon('people')}<h3>Identitas perusahaan</h3><p>Kontak bersama untuk konten dan dokumen baru. Dokumen yang telah diterbitkan mempertahankan data sebelumnya.</p></div>${B115('Ubah identitas','company','','small')}</section><section class="linked115"><div>${icon('shield')}<h3>Dokumen operasional terpisah</h3><p>Kontrak Label dan standar kredit dikelola dari menu asal. Berkas KTP, tanda tangan, dan stempel tidak masuk konten publik.</p></div><div class="buttons115">${B115('Kontrak Label ↗','source','contracts','text')}${B115('Paket & Kredit ↗','source','plans','text')}${B115('Standar & Penanda ↗','source','standards','text')}</div></section>`}
function navCanPreview115(x){const key=ui115.target;if(!key.startsWith('admin'))return true;const u=user114(ui115.navStaff);if(!u||u.super||u.status!=='active')return false;const map={work:'releases',labels:'labels',monitor:'royalty',releases:'releases',royalty:'royalty',withdraw:'withdraw',transactions:'transactions',addons:'services',wami:'wami',tickets:'tickets'};return !map[x.id]||Staff114.can(model114(),u.id,map[x.id]+'.view')}
function navigationPage115(){const n=draft115('navigation').targets[ui115.target];return `<div class="section-head115"><div><h2>Susunan menu per akun</h2><p>Nama, kelompok, urutan, dan visibilitas. Tidak menambah izin akses.</p></div>${B115('Tambah kelompok','group-new','','small')}</div><div class="filters115"><label>Tampilan akun<select id="target115">${Object.entries(targetNames115).map(([id,l])=>`<option value="${id}" ${id===ui115.target?'selected':''}>${l}</option>`).join('')}</select></label>${ui115.target.startsWith('admin')?`<label>Pratinjau akses staff<select id="nav-staff115">${model114().users.filter(u=>!u.super&&u.status==='active').map(u=>`<option value="${u.id}" ${u.id===ui115.navStaff?'selected':''}>${E(u.name)}</option>`).join('')}</select></label>`:''}</div><div class="nav-layout115"><section class="list115 nav-list115">${n.items.map((x,i)=>`<article class="nav-row115 ${x.parent?'child115':''}" draggable="true" data-drag115="${x.id}"><span class="drag115" title="Tarik untuk mengubah urutan">⠿</span><button class="nav-name115" data-s115="nav-item" data-id="${x.id}">${icon(x.icon)}<span><strong>${E(x.name)}</strong><small>${E(x.en)}${x.group?' · '+E(n.groups.find(g=>g.id===x.group)?.name||''):''}${x.parent?' · Submenu':''}</small></span></button><div class="buttons115">${!x.visible?statusBadge111('Tersembunyi','neutral'):''}${B115('↑','move',x.id+':-1','text')}${B115('↓','move',x.id+':1','text')}</div></article>`).join('')}${n.groups.map(g=>`<div class="group-row115"><strong>${E(g.name)}</strong><span>${n.items.filter(x=>x.group===g.id).length} menu</span>${B115('Ubah','group',g.id,'text')}${B115('Hapus','group-delete',g.id,'text')}</div>`).join('')}</section><aside class="nav-preview115"><div class="section-head115"><strong>Pratinjau sidebar</strong><span>${ui115.target.startsWith('admin')?E(user114(ui115.navStaff)?.name||'Pilih staff'):'RM'}</span></div>${previewNav115(n)}</aside></div>`}
function previewNav115(n){const shown=n.items.filter(x=>x.visible&&navCanPreview115(x)),groups=[{id:'',name:''},...n.groups];return groups.map(g=>`<div>${g.name?`<small class="group-title115">${E(g.name)}</small>`:''}${shown.filter(x=>!x.parent&&(x.group||'')===g.id).map(x=>`<div class="preview-link115 ${x.id==='home'?'active':''}">${icon(x.icon)}<span>${E(ten.lang==='en'?x.en:x.name)}</span></div>${shown.filter(y=>y.parent===x.id).map(y=>`<div class="preview-link115 child115">${icon(y.icon)}<span>${E(ten.lang==='en'?y.en:y.name)}</span></div>`).join('')}`).join('')}</div>`).join('')}
