function proceduresPage115(){const v=draft115('procedures'),list=v.rules.filter(r=>(ui115.module==='all'||r.id===ui115.module)&&(ui115.kind==='all'||r.mode===ui115.kind));return `<div class="section-head115"><div><h2>Aturan waktu & tindak lanjut</h2><p>Waktu internal, menunggu Label, pihak luar, dan periode tetap dibedakan.</p></div>${B115('Kalender operasional','calendar','','small')}</div><div class="filters115"><select id="rule-module115" aria-label="Filter prosedur"><option value="all">Semua prosedur</option>${v.rules.map(r=>`<option value="${r.id}" ${ui115.module===r.id?'selected':''}>${E(L(r.name))}</option>`).join('')}</select><select id="rule-kind115" aria-label="Filter dasar waktu"><option value="all">Semua dasar waktu</option>${['working','nextday','monthly','release'].map(k=>`<option value="${k}" ${ui115.kind===k?'selected':''}>${basis115({mode:k})}</option>`).join('')}</select></div><section class="list115">${list.map(r=>row115(L(r.name),L(r.desc),`<strong>${r.mode==='monthly'?'1–14 / 15–20':r.mode==='nextday'?'Tanggal berganti':r.value+' '+basis115(r).toLowerCase()}</strong>`,'rule',r.id)).join('')||'<p class="empty115">Tidak ada aturan sesuai filter.</p>'}</section><section class="list115 extra-rules115">${row115('Tahapan WAMI','Antrean, penanganan, perbaikan Label, dan tindak lanjut pihak luar.',`<strong>${v.wami.queueWarn} / ${v.wami.queueDue} jam kerja</strong>`,'wami','')}${row115('Tindak lanjut distributor','Tiket yang diteruskan mempertahankan hasil dan menunggu tindak lanjut.',`<strong>${v.ticketDays} hari kerja</strong>`,'ticket','')}${row115('Perbaikan rilisan','Dihitung dari permintaan perbaikan yang dikirim, termasuk akhir pekan.',`<strong>${v.revisionHours} jam kalender</strong>`,'revision','')}</section><div class="policy-note115">${icon('clock')}<p>Membuka pekerjaan atau menambah catatan tidak mereset waktu. Pengingat tidak membatalkan pekerjaan, memotong kredit, atau mengubah KPI.</p></div>`}
function drawer115(title,body,footer=''){let d=document.querySelector('#system-drawer115');if(!d){d=document.createElement('dialog');d.id='system-drawer115';d.setAttribute('aria-labelledby','system-title115');d.className='drawer114 drawer115';d.addEventListener('cancel',e=>{e.preventDefault();close115()});d.addEventListener('click',e=>{if(e.target===d)close115()});document.body.append(d)}d.innerHTML=`<header><div><small>SISTEM / ${T(...tabs115[ui115.tab])}</small><h2 id="system-title115">${E(title)}</h2></div>${B115('×','close','','close114')}</header><div class="drawer-body115">${body}</div>${footer?`<footer class="drawer-foot115">${footer}</footer>`:''}`;d.querySelector('[data-s115=close]')?.setAttribute('aria-label',T('Tutup panel','Close panel'));if(!d.open)d.showModal();d.scrollTop=0;return d}
function close115(force=false){const d=document.querySelector('#system-drawer115');if(!force&&ui115.dirty&&ui115.editor){const form=d.querySelector('form[data-editor115]');if(form){d.querySelector('.leave115')?.remove();d.querySelector('.drawer-body115').insertAdjacentHTML('afterbegin',`<div class="leave115" role="alert"><strong>Perubahan belum disimpan</strong><p>Simpan draf sebelum keluar, atau buang isian ini.</p><div class="buttons115">${B115('Simpan draf','save-leave','','primary')}${B115('Buang perubahan','leave-discard','','text')}${B115('Tetap mengedit','leave-stay','','text')}</div></div>`);return}}d?.close();ui115.editor=null;ui115.review=null;ui115.dirty=false}
function input115(name,label,value,type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${E(value)}" ${extra}></label>`}
function textarea115(name,label,value,extra=''){return `<label>${label}<textarea name="${name}" rows="4" ${extra}>${E(value||'')}</textarea></label>`}
