function editor115(area,type,id,title,fields){const a=area115(area);ui115.editor={area,type,id,version:a.version,draftVersion:a.draftVersion,source:System115.cp(draft115(area))};ui115.dirty=false;drawer115(title,`<form data-editor115="${type}">${fields}${error115()}<div class="form-foot115"><span>Perubahan belum diterapkan kepada pengguna.</span><button class="btn primary" type="submit">Simpan draf</button></div></form>`);document.querySelector('.form-foot115>span').textContent='Perubahan belum diterapkan kepada pengguna.'}
