function blockEditor115(id){const b=draft115('content').blocks[id];editor115('content','block',id,contentNames115[id],`${input115('title','Judul',b.title,'text','required maxlength="160"')}${textarea115('text','Penjelasan',b.text,'maxlength="5000"')}<label class="check115"><input name="visible" type="checkbox" ${b.visible?'checked':''}>Tampilkan bagian ini</label>${id==='hero'?`${input115('cta','Teks tombol',b.cta)}${input115('link','Tujuan tombol',b.link)}<label>Gambar pembuka<input id="image115" type="file" accept="image/png,image/jpeg,image/webp"></label><div id="image-preview115">${b.image?`<img src="${E(b.image)}" alt="Gambar pembuka">`:''}</div>${B115('Hapus gambar','image-clear','','text')}`:''}${['benefits','flow','faq'].includes(id)?itemsEditor115(b.items||[]):''}${id==='offers'?'<p class="policy-note115">Harga dan benefit dibaca dari Paket & Kredit; tidak diketik ulang di konten.</p>':''}`)}
function companyEditor115(){const c=draft115('content').company;editor115('content','company','company','Identitas perusahaan',`${input115('name','Nama badan usaha',c.name,'text','required')}${input115('email','Email kontak',c.email,'email')}${input115('phone','Telepon',c.phone)}${textarea115('address','Alamat perusahaan',c.address)}<p class="policy-note115">Data ini untuk konten publik dan dokumen baru. Kontrak, invoice, dan dokumen lama tidak ditulis ulang.</p>`)}
function navEditor115(id){const n=draft115('navigation').targets[ui115.target],x=n.items.find(x=>x.id===id),children=n.items.filter(y=>y.parent===id);editor115('navigation','nav',id,'Menu · '+x.name,`${input115('name','Nama Bahasa Indonesia',x.name,'text','required maxlength="60"')}${input115('en','Nama Bahasa Inggris',x.en,'text','required maxlength="60"')}<label>Ikon<select name="icon">${['grid','people','release','wallet','music','shield','spark','support','settings','clock','activity','menu'].map(v=>`<option ${x.icon===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Kelompok<select name="group"><option value="">Tanpa kelompok</option>${n.groups.map(g=>`<option value="${g.id}" ${x.group===g.id?'selected':''}>${E(g.name)}</option>`).join('')}</select></label><label>Menu induk<select name="parent" ${x.protected||children.length?'disabled':''}><option value="">Tingkat utama</option>${n.items.filter(y=>y.id!==id&&!y.parent&&!y.protected).map(y=>`<option value="${y.id}" ${x.parent===y.id?'selected':''}>${E(y.name)}</option>`).join('')}</select></label><label class="check115"><input name="visible" type="checkbox" ${x.visible?'checked':''} ${x.protected?'disabled':''}>Tampilkan di navigasi</label><p class="policy-note115">${x.protected?'Menu ini wajib tetap terlihat.':children.length?'Menu ini memiliki '+children.length+' submenu. Pindahkan atau sembunyikan anak terlebih dahulu jika induk akan disembunyikan.':'Visibilitas tidak mengubah hak akses. Tautan tetap mengikuti izin Staff & Akses.'}</p>`);ui115.editor.target=ui115.target}
function groupEditor115(id){const n=draft115('navigation').targets[ui115.target],g=n.groups.find(g=>g.id===id)||{name:'',en:''};editor115('navigation','group',id||'','Kelompok menu',`${input115('name','Nama kelompok ID',g.name,'text','required maxlength="60"')}${input115('en','Nama kelompok EN',g.en,'text','required maxlength="60"')}`);ui115.editor.target=ui115.target}
function ruleEditor115(id){const r=draft115('procedures').rules.find(r=>r.id===id);editor115('procedures','rule',id,L(r.name),`<div class="flow115"><span>Masuk tahap</span><i>→</i><span>${E(basis115(r))}</span><i>→</i><span>Atensi & tindak lanjut</span></div><p>${E(L(r.desc))}</p>${r.mode==='monthly'?'<dl class="facts115"><div><dt>Pengajuan</dt><dd>Tanggal 1–14</dd></div><div><dt>Pembayaran</dt><dd>Tanggal 15–20</dd></div></dl><p class="policy-note115">Mulai tanggal 21, pembayaran yang belum selesai memunculkan peringatan. Jadwal ini mempertahankan kebijakan yang sudah disepakati.</p>':r.mode==='nextday'?'<p class="policy-note115">Pekerjaan menjadi prioritas pada pergantian tanggal WIB. Ini bukan batas 24 jam.</p>':input115('value','Batas · '+basis115(r),r.value,'number','required min="1" max="720"')}<section class="section115"><h3>Penerima pengingat</h3><p>Penanggung jawab sesuai tahap; Label hanya menerima kebutuhan yang harus ia lengkapi. Super Admin melihat perkara yang membutuhkan kewenangannya.</p><h3>Perilaku aturan</h3><p>Waktu tunggu pihak luar dipisahkan dari penanganan internal. Catatan biasa tidak memulai hitungan baru.</p></section>`)}
function extraRuleEditor115(type){const v=draft115('procedures');if(type==='calendar')return editor115('procedures','calendar','','Kalender operasional',`<fieldset class="days115"><legend>Hari kerja</legend>${['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'].map((n,i)=>`<label class="check115"><input name="days" type="checkbox" value="${i}" ${v.calendar.days.includes(i)?'checked':''}>${n}</label>`).join('')}</fieldset><div class="form-grid115">${input115('start','Jam buka · WIB',v.calendar.start,'time','required')}${input115('end','Jam tutup · WIB',v.calendar.end,'time','required')}</div>${textarea115('holidays','Tanggal libur · satu YYYY-MM-DD per baris',v.calendar.holidays.join('\n'))}<p class="policy-note115">Kalender hanya memengaruhi hitungan jam/hari kerja operasional. Waktu kalender dan jadwal bulanan tetap berjalan. Tidak mengubah catatan absensi atau payroll.</p>`);if(type==='wami')return editor115('procedures','wami','','Tahapan WAMI',Object.entries(v.wami).map(([k,n])=>input115(k,fields115[k]+' · '+(k==='externalDays'?'hari kerja':k.startsWith('label')?'jam kalender':'jam kerja'),n,'number','min="1" max="720" required')).join('')+'<p class="policy-note115">Urutan pengingat wajib meningkat. Tindak lanjut pihak luar bukan janji hasil WAMI selesai.</p>');editor115('procedures',type,'',type==='ticket'?'Tindak lanjut distributor':'Perbaikan rilisan',input115('value',type==='ticket'?'Hari kerja setelah diteruskan':'Jam kalender sejak perbaikan diminta',type==='ticket'?v.ticketDays:v.revisionHours,'number',`min="1" max="${type==='ticket'?90:720}" required`)+'<p class="policy-note115">Pengingat tidak menutup pengajuan dan tidak mengembalikan atau memotong kredit.</p>')}
function collectEditor115(f){const e=ui115.editor,v=System115.cp(e.source),fd=new FormData(f),get=k=>String(fd.get(k)||'').trim();if(e.type==='block'){const b=v.blocks[e.id];Object.assign(b,{title:get('title'),text:get('text'),visible:fd.has('visible')});if(e.id==='hero')Object.assign(b,{cta:get('cta'),link:get('link'),image:e.image??b.image});if(['benefits','flow','faq'].includes(e.id))b.items=[...f.querySelectorAll('.item-edit115')].map(n=>({title:n.querySelector('[name=item-title]').value.trim(),text:n.querySelector('[name=item-text]').value.trim()}));}
if(e.type==='company')v.company={name:get('name'),email:get('email').toLowerCase(),phone:get('phone'),address:get('address')};if(e.type==='nav'){const x=v.targets[e.target].items.find(x=>x.id===e.id);Object.assign(x,{name:get('name'),en:get('en'),icon:get('icon'),group:get('group'),parent:f.elements.parent.disabled?x.parent:get('parent'),visible:x.protected?true:fd.has('visible')});}if(e.type==='group'){const n=v.targets[e.target],g=n.groups.find(g=>g.id===e.id);if(g)Object.assign(g,{name:get('name'),en:get('en')});else n.groups.push({id:'g'+now115()+'-'+n.groups.length,name:get('name'),en:get('en')});}if(e.type==='calendar')v.calendar={days:fd.getAll('days').map(Number),start:get('start'),end:get('end'),holidays:get('holidays').split(/\s+/).filter(Boolean)};if(e.type==='wami')for(const k of Object.keys(v.wami))v.wami[k]=Number(fd.get(k));if(e.type==='rule'&&f.elements.value)v.rules.find(r=>r.id===e.id).value=Number(fd.get('value'));if(e.type==='ticket')v.ticketDays=Number(fd.get('value'));if(e.type==='revision')v.revisionHours=Number(fd.get('value'));return v}
function saveEditor115(f,leave=false){try{const e=ui115.editor,value=collectEditor115(f);atomic115('save',{area:e.area,version:e.version,draftVersion:e.draftVersion,value});ui115.dirty=false;close115(true);render();toast('Draf tersimpan. Belum diterapkan.')}catch(err){showError115(err.message)}}
function showError115(msg){const d=document.querySelector('#system-drawer115'),e=d?.querySelector('.error115');if(e&&d.open){e.hidden=false;e.textContent=msg;e.scrollIntoView({block:'nearest'})}else toast(msg)}
function diffText115(v){if(v===null)return '—';if(typeof v==='boolean')return v?'Ya':'Tidak';const t=typeof v==='object'?JSON.stringify(System115.safe(v)):String(v);return t.startsWith('data:')?'Gambar diperbarui':t.length>400?t.slice(0,400)+'…':t}
function diffLabel115(path){return path.split('.').map(k=>fields115[k]||contentNames115[k]||targetNames115[k]||(/^\d+$/.test(k)?'Item '+(Number(k)+1):k)).join(' / ')}
function diffHtml115(diff){return `<div class="diff-list115">${diff.map(x=>`<article><strong>${E(diffLabel115(x.field))}</strong><div><span>${E(diffText115(x.before))}</span><i>→</i><span>${E(diffText115(x.after))}</span></div></article>`).join('')||'<p>Belum ada perubahan.</p>'}</div>`}
function review115(area){const a=area115(area);if(!a.draft)return toast('Simpan draf terlebih dahulu.');const diff=System115.changed(a.published,a.draft);ui115.review={area,version:a.version,draftVersion:a.draftVersion,impact:area==='procedures'?impact115(a.draft):[],source:System115.cp(a.draft)};ui115.editor=null;ui115.dirty=false;const ids=area==='content'?[...Object.keys(contentNames115),'company'].filter(id=>JSON.stringify(id==='company'?a.published.company:a.published.blocks[id])!==JSON.stringify(id==='company'?a.draft.company:a.draft.blocks[id])):[];
drawer115(area==='content'?'Tinjau publikasi':'Tinjau penerapan',`<form data-review115><div class="review-hero115"><span class="row-symbol115">${icon('shield')}</span><div><h3>${diff.length} perubahan</h3><p>Versi ${a.version} → ${a.version+1}</p></div></div>${area==='content'?`<fieldset><legend>Bagian yang dipublikasikan</legend>${ids.map(id=>`<label class="check115"><input name="blocks" type="checkbox" value="${id}" checked>${contentNames115[id]||'Identitas perusahaan'}</label>`).join('')}</fieldset><p>Publikasi hanya mengubah bagian terpilih. Draf bagian lainnya tetap tersimpan. Ini simulasi website publik lokal.</p>`:area==='navigation'?'<p>Pengguna menerima navigasi baru setelah reload. Izin, tema pribadi, formulir aktif, dan tujuan tautan tetap dipertahankan.</p>':area==='maintenance'?'<p>Jadwal yang diterapkan langsung mengatur pengumuman dan tanda baca-saja bagi pengguna. Riwayat jadwal tercatat di versi.</p>':`<p>Default: berlaku pada tahap pekerjaan yang dimulai setelah penerapan.</p><label class="check115"><input name="ongoing" id="ongoing115" type="checkbox">Terapkan juga pada pekerjaan berjalan</label><div id="impact115" hidden>${impactHtml115(ui115.review.impact)}<label class="check115"><input name="confirmed" type="checkbox">Saya telah meninjau perubahan tenggat di atas.</label></div>`}${diffHtml115(diff)}${textarea115('note','Catatan penerapan','','required maxlength="1000"')}${error115()}<div class="form-foot115">${B115('Kembali','close','','text')}<button class="btn primary" type="submit">${area==='content'?'Publikasikan konten':area==='navigation'?'Terapkan navigasi':area==='maintenance'?'Terapkan jadwal':'Terapkan aturan'}</button></div></form>`)}
function versions115(area){const a=area115(area);drawer115('Riwayat versi · '+T(...tabs115[area]),`<div class="version115"><strong>Versi ${a.version} · Aktif</strong><p>${a.appliedAt?fmt115(a.appliedAt):'Dasar awal prototype'}</p>${B115('Lihat konfigurasi aktif','view-version',area+':active','text')}</div>${a.history.map(h=>`<div class="version115"><strong>Versi ${h.version}</strong><p>${E(user114(h.actor)?.name||'Pelaku tidak tercatat')} · ${fmt115(h.at)}</p><p>${E(h.note)}</p><div class="buttons115">${B115('Lihat isi','view-version',area+':'+h.id,'text')}${B115('Pulihkan sebagai draf','restore',area+':'+h.id,'small')}</div></div>`).join('')||'<p>Belum ada versi sebelumnya.</p>'}<p class="policy-note115">Pemulihan membuat draf untuk ditinjau. Tidak mengulang transaksi, kredit, atau tindakan pekerjaan.</p>`)}
function contentPreview115(){const v=ui115.previewContent==='active'?area115('content').published:draft115('content'),b=v.blocks,c=v.company;return `<article class="website-preview115 ${ui115.preview==='mobile'?'mobile115':''}"><header><strong>RILIS MUSIK</strong><span>Pratinjau · ${ui115.preview==='mobile'?'Ponsel':'Desktop'}</span></header>${Object.entries(contentNames115).filter(([id])=>id!=='seo'&&b[id].visible).map(([id])=>`<section class="web-section115 ${id==='hero'?'web-hero115':''}">${b[id].image?`<img src="${E(b[id].image)}" alt="Gambar pembuka">`:''}<small>${E(contentNames115[id])}</small><h2>${E(b[id].title)}</h2><p>${E(b[id].text)}</p>${(b[id].items||[]).map(x=>`<div><h3>${E(x.title)}</h3><p>${E(x.text)}</p></div>`).join('')}${id==='offers'?offersPreview115():''}${id==='hero'&&b[id].cta?`<span class="btn primary">${E(b[id].cta)}</span>`:''}${id==='footer'?`<p>${E(c.name)} · ${E(c.email||'Email belum diisi')}<br>${E(c.phone)}<br>${E(c.address)}</p>`:''}</section>`).join('')}<footer><strong>${E(b.seo.title)}</strong><p>${E(b.seo.text)}</p></footer></article>`}
function offersPreview115(){const c=ten.catalogue104;const plans=c?.plans||c?.packages;return `<div class="offers-source115"><strong>Penawaran dari Paket & Kredit</strong><p>${plans?Object.values(plans).filter(x=>x&&typeof x==='object').map(x=>E(x.name||x.id||'Paket')).join(' · '):'FLEX · GO · PRO · BUSINESS'}</p><small>Harga dan benefit mengikuti katalog; konten tidak mengubah perhitungan pembelian.</small></div>`}
function preview115(area){ui115.editor=null;ui115.dirty=false;if(area==='content')drawer115(ui115.previewContent==='active'?'Website · konten aktif':'Website · pratinjau draf',`<div class="buttons115">${B115('Desktop','preview-device','desktop','small')}${B115('Ponsel','preview-device','mobile','small')}</div>${contentPreview115()}`);else if(area==='navigation')drawer115('Pratinjau navigasi',`<h3>${E(targetNames115[ui115.target])}</h3><p>Menu mengikuti visibilitas dan akses akun yang dipilih.</p>${previewNav115(draft115('navigation').targets[ui115.target])}`);else if(area==='maintenance')drawer115('Pratinjau pengumuman pemeliharaan',`<p>Pesan tampil kepada pengguna mulai dari waktu pengingat tiap jadwal, sesuai draf ini.</p>${draft115('maintenance').windows.map(w=>maintBannerHtml131(w,true)+`<p class="policy-note115">${T(...maintStatus131[w.status])} · ${T('Pengumuman','Announcement')}: ${E(T(...maintNotify131[w.notify]))}</p>`).join('')||'<p>Belum ada jadwal.</p>'}`);else drawer115('Pratinjau aturan waktu',`<p>Contoh menggunakan kalender dan draf baru. Data pekerjaan belum berubah.</p>${impactHtml115(impact115(draft115('procedures')))}<p class="policy-note115">Perubahan pada pekerjaan berjalan memerlukan persetujuan terpisah saat penerapan.</p>`)}
const navEditorOriginal115=navEditor115;navEditor115=function(id){navEditorOriginal115(id);const names={grid:'Dashboard',people:'Akun',release:'Rilisan',wallet:'Keuangan',music:'Musik',shield:'Perlindungan',spark:'Wawasan',support:'Bantuan',settings:'Pengaturan',clock:'Waktu',activity:'Aktivitas',menu:'Navigasi'};document.querySelectorAll('#system-drawer115 select[name=icon] option').forEach(o=>{const value=o.value;o.value=value;o.textContent=names[value]||value})};
const ruleEditorOriginal115=ruleEditor115;ruleEditor115=function(id){ruleEditorOriginal115(id);const r=draft115('procedures').rules.find(x=>x.id===id);if(['monthly','nextday'].includes(r.mode)){const f=document.querySelector('#system-drawer115 [data-editor115]');f.querySelector('.form-foot115')?.remove();f.querySelector('.error115')?.remove();const s=document.createElement('section');while(f.firstChild)s.append(f.firstChild);f.replaceWith(s);ui115.editor=null;ui115.dirty=false;}};
Object.assign(fields115,{email:'Email',role:'Peran',scope:'Cakupan Label',permissions:'Izin tindakan',status:'Status',description:'Penjelasan',order:'Urutan',labels:'Label yang dapat diakses',phone:'Telepon',address:'Alamat perusahaan','document-view':'Dokumen ditinjau'});
